package com.example

import com.example.ExamQuestionHelper.QSpec

object HealthLiveExamNutritionBank2 {
    private const val T = "පෝෂණය, සමබල ආහාරය හා පෝෂණ ඌනතා රෝග"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පූර්ණ විවේකී සුවයෙන් සිටින විට හෘද ස්පන්දනය, ශ්වසනය වැනි මූලික ජීව ක්‍රියා සඳහා වැයවන අවම ශක්ති සීඝ්‍රතාව කුමක්ද?", "පාදස්ථ පරිවෘත්තීය සීඝ්‍රතාව (BMR)", "සම්පූර්ණ ශක්ති අවශ්‍යතාව", "ශාරීරික කාර්යක්ෂමතාව", "චාලක ශක්තිය", "Basal Metabolic Rate යනු ජීවය පවත්වා ගැනීම සඳහා ශරීරය වැය කරන අවම ශක්ති ප්‍රමාණයයි."),
        q("පාදස්ථ පරිවෘත්තීය සීඝ්‍රතාව (BMR) කෙරෙහි ඍජුවම බලපාන අන්තරාසර්ග හෝමෝනය කුමක්ද?", "තයිරොක්සින් හෝමෝනය", "ඉන්සියුලින් හෝමෝනය", "ග්ලුකොගන් හෝමෝනය", "පැරතොමෝනය", "තයිරොක්සින් හෝමෝනය මගින් සෛලීය ඔක්සිජන් පරිභෝජනය හා මූලික පරිවෘත්තීය සීඝ්‍රතාව පාලනය කරයි."),
        q("සාමාන්‍යයෙන් එකම වයසේ හා බරෙහි පසුවන පිරිමියෙකුගේ BMR අගය කාන්තාවකට වඩා ඉහළ වීමට හේතුව කුමක්ද?", "පිරිමින්ගේ දේහයේ මාංශපේශී ප්‍රතිශතය සාපේක්ෂව වැඩිවීම", "පිරිමින්ගේ දේහ උෂ්ණත්වය අඩු වීම", "පිරිමින්ගේ ඇටසැකිල්ල සැහැල්ලු වීම", "පිරිමින් අඩු කැලරි ප්‍රමාණයක් වැය කිරීම", "මාංශපේශී පටක මේද පටකවලට වඩා පරිවෘත්තීයමය වශයෙන් ඉතා සක්‍රීය බැවින් BMR අගය ඉහළ යයි."),
        q("පුද්ගලයෙකු ආහාර මගින් ශරීරයට ලබාගන්නා ශක්තියට වඩා වැඩි ශක්තියක් දෛනිකව වැය කරන්නේ නම් ඇතිවන තත්ත්වය කුමක්ද?", "සෘණ ශක්ති සමතුලිතතාව (ශරීර බර අඩුවේ)", "ධන ශක්ති සමතුලිතතාව (ශරීර බර වැඩිවේ)", "ස්ථාවර බර තත්ත්වය", "අධි ස්ථූලතාව", "වැයවන ශක්තිය ලැබෙන ශක්තියට වඩා වැඩි වූ විට ශරීරයේ මේදය දහනය වී ශරීර බර අඩු වේ."),
        q("ආහාර මගින් ලබාගන්නා කැලරි ප්‍රමාණය දෛනිකව වැය කරන කැලරි ප්‍රමාණයට වඩා අඛණ්ඩව වැඩි වූ විට සිදුවන්නේ කුමක්ද?", "ධන ශක්ති සමතුලිතතාව ඇතිවී ශරීර බර හා මේදය වැඩිවීම", "සෘණ ශක්ති සමතුලිතතාව ඇතිවීම", "ශරීර බර ශීඝ්‍රයෙන් අඩුවීම", "මාංශපේශී දියවී යාම", "අතිරික්ත ශක්තිය ශරීරයේ මේදය ලෙස තැන්පත් වීමෙන් වැඩි බර හා ස්ථූලතාව හටගනී."),
        q("ළමා වර්ධනය අධීක්ෂණය කිරීමේදී 'වයසට සරිලන උස නොමැතිවීම' (නියමිත උසට වඩා මිටිවීම) හඳුන්වන්නේ කෙසේද?", "කුරු බව හෙවත් මිටි බව (Stunting)", "කෘශ බව (Wasting)", "අඩු බර (Underweight)", "ස්ථූලතාව", "Stunting යනු දීර්ඝකාලීන නිදන්ගත මන්දපෝෂණය නිසා දරුවෙකුගේ උස නිසි ලෙස නොවැඩී යාමයි."),
        q("උග්‍ර මන්දපෝෂණය හෝ ක්ෂණික රෝගී තත්ත්වයක් නිසා 'උසට සරිලන බර නොමැතිවීම' හඳුන්වන වර්ධන දර්ශකය කුමක්ද?", "කෘශ බව හෙවත් කෙට්ටු බව (Wasting)", "මිටි බව", "ස්ථූල බව", "අධි බර", "Wasting යනු මෑතකදී ඇති වූ උග්‍ර ආහාර හිඟතාවක් හෝ පාචනය වැනි රෝගයක් නිසා බර අඩුවීමයි."),
        q("දරුවෙකුගේ 'වයසට සරිලන බර නොමැතිවීම' ලෝක සෞඛ්‍ය සංවිධානයේ නිර්ණායක අනුව හඳුන්වන්නේ කුමන නමකින්ද?", "අඩු බර තත්ත්වය (Underweight)", "කෘශ බව", "කුරු බව", "සාමාන්‍ය බර", "Underweight තත්ත්වය දරුවාගේ වයස හා බර සැසඳීමෙන් මනිනු ලබන මූලික දර්ශකයකි."),
        q("ශ්‍රී ලංකාවේ දරුවන්ගේ උපතේ සිට වර්ධනය සටහන් කර පවත්වාගෙන යනු ලබන වෛද්‍ය වාර්තා පොත කුමක්ද?", "ළමා සෞඛ්‍ය සංවර්ධන සටහන් පොත (CHDR)", "පාසල් සෞඛ්‍ය වාර්තාව", "සායනික ප්‍රතිකාර පොත", "ክትባት සහතික පත්‍රය", "ළමා සෞඛ්‍ය සංවර්ධන සටහන් පොතෙහි ඇති බර-වයස ප්‍රස්තාරය මගින් දරුවාගේ වර්ධනය මාසිකව සටහන් කරයි."),
        q("ළමා වර්ධන ප්‍රස්තාරයක වර්ධන වක්‍රය ඉහළට ගමන් නොකර තිරස්ව (සමාන්තරව) පවතී නම් එයින් අදහස් වන්නේ කුමක්ද?", "දරුවාගේ බර වැඩි වී නොමැති බව සහ අවදානම් සහගත බව", "දරුවා ඉතා වේගයෙන් වර්ධනය වන බව", "දරුවාට කිසිදු පෝෂණ ගැටලුවක් නොමැති බව", "දරුවා අධික බර තත්ත්වයක පසුවන බව", "වර්ධන රේඛාව තිරස් වීම දරුවාගේ බර එකතැන පල්වීමක් වන අතර එය අනතුරු ඇඟවීමේ සංඥාවකි."),
        q("ළමා වර්ධන වක්‍රය පහළට නැඹුරු වී ගමන් කරන්නේ නම් සෞඛ්‍ය නිලධාරීන් විසින් සලකනු ලබන්නේ කුමන තත්ත්වයක් ලෙසද?", "දරුවාගේ බර අඩුවී ඇති බව සහ වහා මැදිහත් විය යුතු අන්තරායකාරී තත්ත්වයක්", "දරුවා නිරෝගීව බර පාලනය කරගන්නා බව", "සාමාන්‍ය වර්ධන තත්ත්වයක් බව", "උස වැඩිවන බව", "වර්ධන වක්‍රය පහළට යාම දරුවා රෝගී වී ඇති බව හෝ බරපතළ පෝෂණ ඌනතාවක පසුවන බව දක්වයි."),
        q("ළදරුවෙකු මෙලොව එළිය දුටු විගස පළමු පැය භාගය ඇතුළත දිය යුතු මව්කිරිවල ඇති කහ පැහැති ඝන දියරය කුමක්ද?", "කොලස්ට්‍රම් හෙවත් මුල් කිරි", "පිටි කිරි", "ග්ලූකෝස් දියරය", "කොත්තමල්ලි වතුර", "කොලස්ට්‍රම්වල රෝගවලින් ආරක්ෂා කරන ප්‍රතිදේහ (විශේෂයෙන් IgA) සහ විටමින් A ඉතා බහුලව ඇත."),
        q("ළදරුවෙකු ඉපදී මුල් මාස 6 සම්පූර්ණ වන තෙක් ජලය පවා අතිරේකව නොදී මව්කිරි පමණක් ලබාදීම හඳුන්වන්නේ කෙසේද?", "පූර්ණ මව්කිරි දීම (Exclusive Breastfeeding)", "අර්ධ මව්කිරි දීම", "අනුපූරක පෝෂණය", "සමබල පෝෂණය", "මුල් මාස 6 තුළ ළදරුවාට අවශ්‍ය සියලුම පෝෂ්‍ය පදාර්ථ හා ජලය මව්කිරිවලින් සම්පූර්ණයෙන්ම ලැබේ."),
        q("මව්කිරි දීම මවගේ සෞඛ්‍යයට යහපත් වීමට ප්‍රධාන හේතුවක් නොවන්නේ කුමක්ද?", "මවගේ අස්ථිවල කැල්සියම් සම්පූර්ණයෙන්ම ක්ෂය වීම", "මව්කිරි දීමෙන් ගර්භාෂය පෙර තත්ත්වයට හැකිලීම වේගවත් වීම", "පියයුරු හා ඩිම්බකෝෂ පිළිකා අවදානම අඩුවීම", "මව සහ බිළිඳා අතර මානසික බැඳීම ශක්තිමත් වීම", "මව්කිරි දීම මවගේ සෞඛ්‍යයට බෙහෙවින් හිතකර වන අතර අස්ථි ක්ෂය වීමක් සිදු නොවේ."),
        q("ළදරුවෙකුට මාස 6 සම්පූර්ණ වූ පසු මව්කිරිවලට අමතරව වෙනත් අර්ධ ඝන ආහාර හඳුන්වා දීම හඳුන්වන්නේ කෙසේද?", "අනුපූරක ආහාර ලබාදීම (Complementary Feeding)", "පූර්ණ මව්කිරි දීම", "කෘත්‍රිම පෝෂණය", "සාමාන්‍ය පවුලේ ආහාර", "මාස 6 න් පසු දරුවාගේ ශක්ති හා යකඩ අවශ්‍යතාව මව්කිරිවලින් පමණක් නොපිරිමහන බැවින් අනුපූරක ආහාර අරඹයි."),
        q("දීර්ඝ ධාවන තරග හෝ පාපැදි තරග සඳහා ඉදිරිපත් වන ක්‍රීඩකයන් තරගයට දින කිහිපයකට පෙර අනුගමනය කරන 'කාබෝහයිඩ්‍රේට් අධිපූරණය' (Carbo-loading) යනු කුමක්ද?", "පේශිවල ග්ලයිකොජන් සංචිත උපරිම මට්ටමකට ගෙන ඒම සඳහා පිෂ්ඨය බහුල ආහාර ගැනීම", "තරගයට පෙර දින අධික ලෙස ප්‍රෝටීන් කුඩු පානය කිරීම", "සිරුරේ ජලය අඩු කර බර අඩු කර ගැනීම", "මේදය පමණක් ආහාරයට ගැනීම", "කාබෝහයිඩ්‍රේට් අධිපූරණය මගින් පේශිවල ග්ලයිකොජන් ධාරිතාව වැඩි කර විඩාව ප්‍රමාද කරයි."),
        q("ක්‍රීඩකයෙකු පුහුණුවීම් හෝ තරගයක නිරත වන අතරතුර සෑම විනාඩි 15-20 කට වරක් ජලය හෝ ක්‍රීඩා පාන මිලිලීටර් කීයක් පානය කළ යුතුද?", "මිලිලීටර් 150 සිට 200 දක්වා ස්වල්ප ප්‍රමාණයක්", "ලීටර් 2ක් එකවර", "මිලිලීටර් 10ක් පමණ", "කිසිසේත් ජලය නොබිය යුතුය", "ව්‍යායාම අතරතුර සුළු ප්‍රමාණවලින් නිතර ජලය පානය කිරීමෙන් විජලනය හා ආමාශයික අපහසුතා වළකී."),
        q("ක්‍රීඩා පුහුණුව අවසන් වූ වහාම ශරීරයේ ක්ෂය වූ ග්ලයිකොජන් යථා තත්ත්වයට පත් කිරීමට සහ මාංශපේශී ප්‍රතිසංස්කරණයට සුදුසුම සංකලනය කුමක්ද?", "කාබෝහයිඩ්‍රේට් සහ ප්‍රෝටීන් අඩංගු සැහැල්ලු ආහාරයක්", "අධික තෙල් සහිත බැදුම් ආහාර", "අයිස්ක්‍රීම් සහ චොකලට්", "ලුණු අධික අච්චාරු", "ව්‍යායාමයෙන් පසු මිනිත්තු 30-45 ඇතුළත කාබෝහයිඩ්‍රේට් හා ප්‍රෝටීන් 3:1 හෝ 4:1 අනුපාතයට ගැනීමෙන් පේශි යථා තත්ත්වයට පත්වේ."),
        q("ආහාර දූෂණය වීමට බලපාන ජීව විද්‍යාත්මක සාධකයකට නිදසුනක් කුමක්ද?", "ව්‍යාධිජනක බැක්ටීරියා, වෛරස් සහ දිලීර", "ආහාරයට වැටෙන ගල් කැට හා වැලි", "කෘමිනාශක සහ වල්නාශක අවශේෂ", "ඊයම් සහ රසදිය වැනි බර ලෝහ", "බැක්ටීරියා (සැල්මොනෙල්ලා ආදී) සහ දිලීර මගින් ආහාර දූෂණය වීම ජීව විද්‍යාත්මක උපද්‍රවයකි."),
        q("අස්වනු නෙලීමේදී හෝ ආහාර සැකසීමේදී ආහාරයට වැටෙන ගල් කැට, වීදුරු කැබලි සහ හිසකෙස් අයත් වන්නේ කුමන උපද්‍රව කාණ්ඩයටද?", "භෞතික උපද්‍රව (Physical Hazards)", "රසායනික උපද්‍රව", "ජීව විද්‍යාත්මක උපද්‍රව", "විකිරණශීලී උපද්‍රව", "ආහාරයේ අඩංගු වන නොදිරවන බාහිර ද්‍රව්‍ය භෞතික දූෂක ලෙස සැලකේ."),
        q("කෘෂිකර්මාන්තයේදී අධික ලෙස භාවිත කරන කෘමිනාශක, රසායනික පොහොර හා පශු ඖෂධ අවශේෂ ආහාරයට එක්වීම කුමන උපද්‍රවයක්ද?", "රසායනික උපද්‍රව (Chemical Hazards)", "භෞතික උපද්‍රව", "ජීව විද්‍යාත්මක උපද්‍රව", "යාන්ත්‍රික උපද්‍රව", "කෘමිනාශක, කල්තබා ගන්නා රසායන හා බැර ලෝහ රසායනික ආහාර දූෂක වේ."),
        q("පිම්බුණු, මලකඩ කෑ හෝ තැලී විකෘති වූ ටින් කළ ආහාර පරිභෝජනය නොකළ යුත්තේ කුමන මාරාන්තික බැක්ටීරියා විෂ නිසාද?", "ක්ලොස්ට්‍රිඩියම් බොටියුලයිනම් (Clostridium botulinum)", "ලැක්ටොබැසිලස්", "ඊස්ට් දිලීර", "ඇසිටොබැක්ටර්", "නිර්වායු පරිසරයේ වැඩෙන ක්ලොස්ට්‍රිඩියම් බැක්ටීරියාව බොටියුලිස්ම් (Botulism) නම් මාරාන්තික ස්නායු විෂ නිපදවයි."),
        q("නියමිත පරිදි වියළා නොගෙන තෙතමනය සහිතව ගබඩා කර ඇති රටකජු සහ බඩඉරිඟුවල ඇස්පර්ගිලස් දිලීරය මගින් නිපදවන අක්මා පිළිකාකාරක විෂ කුමක්ද?", "ඇෆ්ලටොක්සින් (Aflatoxin)", "බොටියුලිනම් විෂ", "හයිඩ්‍රජන් සයනයිඩ්", "එතනෝල්", "තෙතමනය සහිත ධාන්‍යවල හැදෙන Aspergillus flavus දිලීරය මගින් ඇෆ්ලටොක්සින් නිපදවන අතර එය අක්මාවට ඉතා විෂ සහිතය."),
        q("අමු හෝ බාගෙට තැම්බූ කුකුළු මස් සහ බිත්තර පරිභෝජනය කිරීමෙන් බහුලව වැළඳෙන ආහාර විෂවීමේ බැක්ටීරියාව කුමක්ද?", "සැල්මොනෙල්ලා (Salmonella)", "ලැක්ටික් බැක්ටීරියාව", "පෙනිසිලියම්", "නයිට්‍රොසොමොනස්", "සැල්මොනෙල්ලා බැක්ටීරියාව මගින් දරුණු උදරාබාධ, පාචනය, උණ හා වමනය හටගනී."),
        q("බැක්ටීරියා ඉතා ශීඝ්‍රයෙන් ගුණනය වන 'ආහාර සුරක්ෂිතතාවේ අනතුරුදායක උෂ්ණත්ව කලාපය' (Danger Zone) කුමක්ද?", "සෙල්සියස් අංශක 5 සිට 60 දක්වා (5°C - 60°C)", "සෙල්සියස් අංශක 0 ට අඩු උෂ්ණත්වය", "සෙල්සියස් අංශක 75 ට වැඩි උෂ්ණත්වය", "සෙල්සියස් අංශක 100 ට වැඩි උෂ්ණත්වය", "5°C ත් 60°C ත් අතර උෂ්ණත්වයේදී ක්ෂුද්‍රජීවීන් ඉතා වේගයෙන් ගුණනය වන බැවින් ආහාර මෙම පරාසයේ වැඩිවේලාවක් නොතැබිය යුතුය."),
        q("පිසූ ආහාර ක්ෂුද්‍රජීවී වර්ධනයෙන් තොරව තබාගැනීම සඳහා ශීතකරණයක සාමාන්‍ය කුටීරයේ (Cooler) තිබිය යුතු උෂ්ණත්වය කුමක්ද?", "සෙල්සියස් අංශක 1 සිට 4 දක්වා (1°C - 4°C)", "සෙල්සියස් අංශක 15 සිට 20 දක්වා", "සෙල්සියස් අංශක 25 සිට 30 දක්වා", "සෙල්සියස් අංශක 0 ට වඩා අඩු උෂ්ණත්වය", "ශීතකරණයක උෂ්ණත්වය 4°C ට අඩුවෙන් පවත්වා ගැනීමෙන් බැක්ටීරියා ගුණනය වීම ඉතා මන්දගාමී වේ."),
        q("මස්, මාළු වැනි ආහාර දිගුකාලීනව ක්ෂුද්‍රජීවී ක්‍රියාකාරිත්වයෙන් තොරව තබාගැනීමට ගැඹුරු අධිශීතකරණයක (Freezer) තිබිය යුතු සම්මත උෂ්ණත්වය කුමක්ද?", "සෙල්සියස් අංශක සෘණ 18 හෝ ඊට අඩු (-18°C)", "සෙල්සියස් අංශක 0ක්", "සෙල්සියස් අංශක 10ක්", "සෙල්සියස් අංශක සෘණ 2ක්", "-18°C උෂ්ණත්වයේදී ක්ෂුද්‍රජීවී වර්ධනය සහ එන්සයිම ක්‍රියාකාරිත්වය සම්පූර්ණයෙන්ම පාහේ අත්හිටුවයි."),
        q("ලෝක සෞඛ්‍ය සංවිධානය (WHO) විසින් ප්‍රකාශිත ආරක්ෂිත ආහාර සඳහා වූ ප්‍රධාන පණිවිඩ 5 (Five Keys) ට අයත් නොවන කරුණ කුමක්ද?", "ආහාර පිසීමේදී අධික ලෙස තෙල් සහ ලුණු එක්කිරීම", "පිරිසිදුව තබා ගැනීම", "පිසූ ආහාර සහ අමු ආහාර වෙන්කර තැබීම", "ආහාර හොඳින් පිසීම (70°C ට වඩා රත් කිරීම)", "WHO පංච මූලධර්මවලට පිරිසිදුකම, වෙන්කර තැබීම, හොඳින් පිසීම, සුදුසු උෂ්ණත්වයේ තැබීම හා පිරිසිදු ජලය භාවිතය අයත් වේ."),
        q("ආහාර පිසීමේදී ආහාරයේ අභ්‍යන්තර උෂ්ණත්වය අවම වශයෙන් සෙල්සියස් අංශක කීයකට වඩා ඉහළ නැංවිය යුතුද?", "සෙල්සියස් අංශක 70ක් හෝ ඊට වැඩි (70°C)", "සෙල්සියස් අංශක 30ක්", "සෙල්සියස් අංශක 45ක්", "සෙල්සියස් අංශක 55ක්", "70°C ට වඩා රත් කිරීමෙන් බොහෝ ව්‍යාධිජනක ක්ෂුද්‍රජීවීන් තත්පර 30ක් ඇතුළත විනාශ වේ."),
        q("ආහාර නිෂ්පාදනයක අඩංගු අමුද්‍රව්‍ය ලැයිස්තුවේ (Ingredients) අමුද්‍රව්‍ය නම් පෙළගස්වා ඇති නිවැරදි පිළිවෙළ කුමක්ද?", "ආහාරයේ අඩංගු බර හෝ ප්‍රතිශතය වැඩිම අමුද්‍රව්‍යයේ සිට අඩුම අමුද්‍රව්‍ය දක්වා අනුපිළිවෙළින්", "අකාරාදී පිළිවෙළට පමණි", "අඩුම අමුද්‍රව්‍යයේ සිට වැඩිම අමුද්‍රව්‍ය දක්වා", "නිෂ්පාදකයාට කැමති ඕනෑම ආකාරයකට", "ආහාර ලේබල් රෙගුලාසි අනුව වැඩිම බරක් සහිත අමුද්‍රව්‍ය මුලින්මද අඩුම ඒවා අවසානයටද දැක්විය යුතුය."),
        q("වෙළඳපොළේ අලෙවි කරන ආහාර පැකට්ටුවක සඳහන් 'කාණ්ඩ අංකය' (Batch Number) වැදගත් වන්නේ ඇයි?", "යම් දෝෂයක් ඇතිවුවහොත් අදාළ නිෂ්පාදන තොගය හඳුනාගෙන වෙළඳපොළෙන් ඉවත් කර ගැනීමට", "ආහාරයේ රසය මැනීමට", "ආහාරයේ මිල තීරණය කිරීමට", "පාරිභෝගිකයාගේ වයස තීරණය කිරීමට", "Batch අංකය මගින් නිෂ්පාදනය කළ දිනය, වේලාව හා යන්ත්‍රය සොයාගෙන දෝෂ සහිත තොග ආපසු කැඳවිය හැක."),
        q("ජානමය වශයෙන් වෙනස් කරන ලද ආහාර (GMO Foods) සම්බන්ධයෙන් පාරිභෝගිකයාට ඇති අයිතිය කුමක්ද?", "ආහාර ලේබලයේ ඒ බව පැහැදිලිව සඳහන් කර තිබීම (GMO Labeling)", "එවැනි ආහාර නොමිලේ ලබාදීම", "රහසිගතව අලෙවි කිරීම", "මිල දෙගුණයක් කිරීම", "GMO ආහාර පරිභෝජනය පිළිබඳ තීරණය කිරීමට පාරිභෝගිකයාට තොරතුරු දැනගැනීමේ අයිතිය ඇත."),
        q("ශ්‍රී ලංකා ප්‍රමිති ආයතනය (SLSI) මගින් උසස් තත්ත්වයේ නිෂ්පාදන සඳහා ලබාදෙන තත්ත්ව සහතික ලකුණ කුමක්ද?", "SLS ලකුණ", "ISO 9001 පමණි", "CE ලකුණ", "WHO ලකුණ", "SLS සහතිකය මගින් අදාළ ආහාරය ශ්‍රී ලංකා ප්‍රමිතීන්ට අනුකූලව ආරක්ෂිතව නිපදවා ඇති බව සනාථ කරයි."),
        q("ආහාරවලට කෘත්‍රිම වර්ණක එක්කිරීමේදී අනුමත නොකළ තහනම් වර්ණකයක් (උදා. ටාට්‍රසින් වෙනුවට කාර්මික සායම්) යෙදීමෙන් සිදුවිය හැකි අහිතකර ප්‍රතිඵලය කුමක්ද?", "අක්මා හා වකුගඩු ආබාධ සහ පිළිකා ඇතිවීම", "ශරීර බර අඩු වීම", "පෙනීම තියුණු වීම", "අස්ථි ශක්තිමත් වීම", "රෙදි සායම් වැනි කාර්මික ඩයි වර්ග ආහාරයට එක්කිරීමෙන් සෛල විකෘති වී පිළිකා ඇතිවේ."),
        q("ආහාර පිරමිඩය අනුව දිනපතා අවම වශයෙන් පලතුරු වර්ග සහ එළවළු වර්ග කීයක් ආහාරයට එකතු කරගත යුතුද?", "එළවළු කොටස් 3ක් සහ පලතුරු කොටස් 2ක් අවම වශයෙන්", "සතියකට එක් වරක් පමණි", "එළවළු කොටස් 10ක්", "පලතුරු කිසිසේත් නොගත යුතුය", "දිනපතා විවිධ වර්ණයන්ගෙන් යුතු එළවළු සහ පලතුරු කොටස් 5ක් ගැනීම නිදන්ගත රෝග වළක්වයි."),
        q("දිනපතා ආහාර වේලෙහි විවිධ වර්ණ 5කින් යුතු එළවළු සහ පලතුරු (Rainbow Diet) ඇතුළත් කරගැනීමේ සෞඛ්‍යමය වාසිය කුමක්ද?", "විවිධ වර්ගයේ ප්‍රතිඔක්සිකාරක සහ ශාක රසායන (Phytochemicals) සිරුරට ලැබීම", "ආහාරයේ කැලරි ප්‍රමාණය ඉතා ඉහළ යාම", "ශරීරයේ මේදය වේගයෙන් තැන්පත් වීම", "ආහාර පිසීම පහසු වීම", "වර්ණක ශාක රසායන මගින් පිළිකා, හෘද රෝග හා සෛල වයස්ගත වීම වළක්වයි."),
        q("පාසල් ආපනශාලාවල විකිණීම තහනම් කර ඇති සෞඛ්‍යයට අහිතකර ආහාර කාණ්ඩයකට නිදසුනක් කුමක්ද?", "ගැඹුරු තෙලේ බදින ලද ආහාර, සොසේජස් සහ කාබනේටඩ් පැණිබීම", "තැම්බූ ධාන්‍ය වර්ග", "නැවුම් පලතුරු සලාද", "එළවළු සුප්", "පාසල් චක්‍රලේඛ අනුව අධික තෙල්, ලුණු, සීනි සහ කෘත්‍රිම රසකාරක සහිත ක්ෂණික ආහාර තහනම්ය."),
        q("ළමා වියේදී අධික ලෙස ක්ෂණික ආහාර (Junk Food) වලට ඇබ්බැහි වීම නිසා පසුකාලීනව බහුලව ඇතිවන බෝ නොවන රෝගය කුමක්ද?", "දෙවන වර්ගයේ දියවැඩියාව සහ අධික රුධිර පීඩනය", "මැලේරියාව", "ක්ෂය රෝගය", "ඩෙංගු උණ", "අධික කැලරි, ලුණු හා සංතෘප්ත මේදය නිසා නව යොවුන් වියේදීම පරිවෘත්තීය ආබාධ හටගනී."),
        q("අස්ථි හා දත්වල ශක්තිමත්භාවය සඳහා කැල්සියම් සමග අනුපාතයකින් අත්‍යවශ්‍ය වන අනෙක් ප්‍රධාන ඛනිජය කුමක්ද?", "පොස්පරස් (P)", "යකඩ", "සෝඩියම්", "අයඩීන්", "කැල්සියම් සහ පොස්පරස් එකතු වී අස්ථිවල හයිඩ්‍රොක්සිඇපටයිට් ස්ඵටික තනයි."),
        q("ශරීරයේ එන්සයිම ක්‍රියාකාරිත්වයන් 300 කට අධික ප්‍රමාණයකට සහභාගී වන ක්ලෝරෝෆිල්හි ප්‍රධාන ඛනිජය කුමක්ද?", "මැග්නීසියම් (Mg)", "සින්ක්", "යකඩ", "තඹ", "මැග්නීසියම් කොළ පැහැති පලා වර්ගවල බහුල වන අතර ස්නායු හා පේශි ක්‍රියාකාරිත්වයට අත්‍යවශ්‍ය වේ."),
        q("දත්වල එනමලය දිරායාම වැළැක්වීම සඳහා සුළු සාන්ද්‍රණයකින් අවශ්‍ය වන නමුත් අධික වූ විට දත්වල දුඹුරු පැහැ ලප ඇතිකරන ඛනිජය කුමක්ද?", "ෆ්ලෝරයිඩ් (Fluoride)", "අයඩීන්", "කැල්සියම්", "පොටෑසියම්", "ෆ්ලෝරයිඩ් අධික වීමෙන් දන්ත ෆ්ලෝරෝසිස් (Dental Fluorosis) තත්ත්වය ඇතිවේ."),
        q("ශරීරයේ හිමොග්ලොබින් සංස්ලේෂණයට යකඩ භාවිත කිරීම සඳහා අත්‍යවශ්‍ය වන උපකාරක ඛනිජය කුමක්ද?", "තඹ (Copper - Cu)", "සෝඩියම්", "ක්ලෝරයිඩ්", "සිලිකන්", "තඹ ඛනිජය යකඩ අවශෝෂණයට හා හිමොග්ලොබින් සෑදීමේ පරිවෘත්තීය ක්‍රියාවලියට උත්ප්‍රේරකයක් ලෙස ක්‍රියා කරයි."),
        q("ග්ලූටතයෝන් පෙරොක්සිඩේස් නම් ප්‍රතිඔක්සිකාරක එන්සයිමයේ ක්‍රියාකාරිත්වයට අවශ්‍ය වන අංශුමාත්‍ර ඛනිජය කුමක්ද?", "සෙලේනියම් (Selenium)", "කැල්සියම්", "මැග්නීසියම්", "පොස්පරස්", "සෙලේනියම් ශරීරයේ සෛල ඔක්සිකාරක හානිවලින් ආරක්ෂා කරන ප්‍රබල අංශුමාත්‍ර මූලද්‍රව්‍යයකි."),
        q("විටමින් B6 (පිරිඩොක්සින්) මගින් ශරීරය තුළ ඉටුකරනු ලබන ප්‍රධාන ජෛව රසායනික කාර්යය කුමක්ද?", "ඇමයිනෝ අම්ල සහ ප්‍රෝටීන් පරිවෘත්තිය නියාමනය කිරීම", "අස්ථිවලට කැල්සියම් බැඳීම", "රුධිරය කැටි ගැසීම", "ඇසේ කඳුළු නිපදවීම", "විටමින් B6 ප්‍රෝටීන හා ඇමයිනෝ අම්ල පරිවෘත්තියේදී සහ එන්සයිම ප්‍රතික්‍රියාවලදී සහ-එන්සයිමයක් ලෙස ක්‍රියා කරයි."),
        q("විටමින් H ලෙසද හඳුන්වන, හිසකෙස් හා නියපොතු නිරෝගීව තබාගැනීමට දායක වන B කාණ්ඩයේ විටමිනය කුමක්ද?", "බයෝටින් (විටමින් B7)", "විටමින් C", "විටමින් A", "විටමින් D", "බයෝටින් මේද අම්ල සංස්ලේෂණයට හා කෙස්/නිය වර්ධනයට අත්‍යවශ්‍ය වේ."),
        q("ශාක ආහාරවල අඩංගු යකඩ (Non-heme Iron) සත්ත්ව ආහාරවල ඇති යකඩ (Heme Iron) වලට වඩා අවශෝෂණය අඩු වීමට හේතුව කුමක්ද?", "ශාක ආහාරවල යකඩ Fe3+ (ෆෙරික්) ලෙස පැවතීම සහ ෆයිටේට අඩංගු වීම", "ශාක ආහාරවල ජලය නොමැති වීම", "ශාක ආහාරවල ප්‍රෝටීන් නොමැති වීම", "ශාක ආහාර තිත්ත රස වීම", "සත්ත්ව ආහාරවල ඇති Fe2+ (ෆෙරස්) යකඩ පහසුවෙන් අවශෝෂණය වන අතර ෆෙරික් යකඩ අවශෝෂණයට විටමින් C අවශ්‍ය වේ."),
        q("ආහාර වේලක අඩංගු 'ෆයිටේට' (ධාන්‍ය කුඩුවල ඇති) සහ 'ඔක්සලේට' (නිවිති ආදියේ ඇති) මගින් ශරීරයට සිදුවන බලපෑම කුමක්ද?", "කැල්සියම් සහ යකඩ වැනි ඛනිජ අවශෝෂණය වීම අඩාල කිරීම", "විටමින් C විනාශ කිරීම", "ප්‍රෝටීන් දහනය කිරීම", "ජලය අවශෝෂණය වැඩි කිරීම", "ෆයිටේට හා ඔක්සලේට ඛනිජ සමග දිය නොවන සංකීර්ණ සාදා ඒවායේ අවශෝෂණය වළක්වයි."),
        q("ධාන්‍ය වර්ග (කඩල, මුං ඇට) පැළවීම (Sprouting) මගින් ඒවායේ පෝෂණ ගුණය ඉහළ යන්නේ ඇයි?", "විටමින් C සහ B ප්‍රමාණය වැඩි වී ෆයිටේට බිඳවැටී ඛනිජ අවශෝෂණය පහසු වන බැවින්", "පිෂ්ඨය ප්‍රමාණය දෙගුණ වන බැවින්", "මේද ප්‍රමාණය අධික වන බැවින්", "ආහාරයේ බර අඩු වන බැවින්", "පැළවීමේදී එන්සයිම සක්‍රීය වී පෝෂක ජීර්ණය පහසු කර විටමින් ප්‍රමාණය බෙහෙවින් ඉහළ නංවයි."),
        q("ආහාර පිසීමේදී බයිකාබනේට් (ආප්ප සෝඩා) යෙදීමෙන් ආහාරයේ විනාශ වී යන සංවේදී විටමින් වර්ගය කුමක්ද?", "විටමින් B1 (තයමින්) සහ විටමින් C", "විටමින් A", "විටමින් D", "විටමින් K", "භෂ්මීය මාධ්‍යයකදී (සෝඩා හමුවේ) තයමින් සහ විටමින් C ඉතා වේගයෙන් වියෝජනය වේ."),
        q("කිරිවල අඩංගු කැල්සියම් ශරීරයට අවශෝෂණය වීම වඩාත් කාර්යක්ෂම වන්නේ කිරිවල කුමන සීනි අඩංගු නිසාද?", "ලැක්ටෝස් සීනි", "සුක්‍රෝස් සීනි", "ෆෲක්ටෝස් සීනි", "ග්ලයිකොජන්", "ලැක්ටෝස් සීනි මගින් කුඩා අන්ත්‍රයේදී කැල්සියම් හා මැග්නීසියම් අවශෝෂණය පහසු කරවයි."),
        q("වැඩිහිටියන්ගේ ආහාර වේලෙහි සංතෘප්ත මේදය වෙනුවට අසංතෘප්ත මේදය භාවිත කිරීමෙන් ලැබෙන හෘද සෞඛ්‍ය වාසිය කුමක්ද?", "රුධිරයේ හිතකර කොලෙස්ටරෝල් (HDL) මට්ටම ආරක්ෂා වී හෘදයාබාධ අවදානම අඩුවීම", "රුධිර පීඩනය ක්ෂණිකව ශුන්‍ය වීම", "රුධිරයේ සීනි එකවර වැඩිවීම", "ශරීර බර අධික ලෙස වැඩිවීම", "අසංතෘප්ත මේද අම්ල (MUFA සහ PUFA) මගින් රුධිර නාල අවහිර වීම වළක්වයි."),
        q("මුහුදු මත්ස්‍යයන්ගේ (සැමන්, ටූනා, මැකරල්) තෙල්වල බහුලව අඩංගු මොළයේ හා හෘදයේ සෞඛ්‍යයට හිතකර මේද අම්ලය කුමක්ද?", "ඔමේගා-3 මේද අම්ල (Omega-3 fatty acids)", "සංතෘප්ත මේදය", "ට්‍රාන්ස් මේද අම්ල", "ස්ටියරික් අම්ලය", "ඔමේගා-3 මේද අම්ල මගින් රුධිර කැටි ගැසීමේ අවදානම අඩු කර මොළයේ සෛල පටල ශක්තිමත් කරයි."),
        q("නිර්මාංශ ආහාර වේලක් පමණක් ගන්නා පුද්ගලයෙකුට (Strict Vegan) සිරුර තුළ ඌන විය හැකි ප්‍රධාන විටමිනය කුමක්ද?", "විටමින් B12 (සයනොකොබලමින්)", "විටමින් C", "විටමින් E", "විටමින් B1", "විටමින් B12 ස්වාභාවිකව අඩංගු වන්නේ සත්ත්ව ආහාරවල පමණක් බැවින් අතිරේක පෙති ලබාගත යුතුය."),
        q("පාසල් දරුවෙකුගේ ආහාර වේලෙහි 'අයඩීන්' නිසි ලෙස නොලැබීමෙන් ඔහුගේ ඉගෙනුම් ක්‍රියාවලියට සිදුවන බලපෑම කුමක්ද?", "මොළයේ ක්‍රියාකාරිත්වය සහ මතක ශක්තිය මන්දගාමී වීම", "පෙනීම සම්පූර්ණයෙන් නැතිවීම", "ශ්‍රවණාබාධ ඇතිවීම", "දත් කැඩී යාම", "ළමා වියේ අයඩීන් ඌනතාවය නිසා බුද්ධි ඵලය (IQ) 10-15% කින් පහත වැටිය හැක."),
        q("අධික ලෙස ලුණු (සෝඩියම් ක්ලෝරයිඩ්) පරිභෝජනය කිරීම නිසා වකුගඩු මගින් රුධිරයට සිදුවන බලපෑම කුමක්ද?", "ශරීරයේ ජලය රඳවාගෙන රුධිර පරිමාව හා රුධිර පීඩනය ඉහළ යාම", "රුධිර පීඩනය අඩුවීම", "රුධිරයේ සීනි ප්‍රමාණය පහත වැටීම", "රුධිරයේ හිමොග්ලොබින් වැඩිවීම", "සෝඩියම් මගින් තරල රඳවා ගැනීම නිසා හෘදයට හා ධමනි බිත්තිවලට අධික පීඩනයක් එල්ල වේ."),
        q("දිනපතා ආහාර වේලෙහි තන්තු (කෙඳි) අධික ආහාර ගැනීමෙන් මහා බඩවැලේ ඇතිවිය හැකි බරපතළ රෝග වළක්වාගත හැක්කේ කෙසේද?", "ආහාරයේ ඇති පිළිකාකාරක විෂ ද්‍රව්‍ය මල සමග ඉක්මනින් බැහැර කිරීම මගින්", "බඩවැල්වල ආහාර දින ගණනක් රඳවා ගැනීමෙන්", "ආහාරයේ ජලය සම්පූර්ණයෙන් ඉවත් කිරීමෙන්", "බඩවැලේ මාංශපේශී ක්ෂය කිරීමෙන්", "කෙඳි මගින් මල ද්‍රව්‍ය ගමන් කිරීමේ කාලය අඩු කර මහාන්ත්‍ර පිළිකා අවදානම වළක්වයි."),
        q("දියවැඩියා රෝගියෙකුට සුදු සහල් සහ සුදු පාන් වෙනුවට නිවුඩු සහල් සහ කුරක්කන් නිර්දේශ කරන්නේ ඇයි?", "ඒවායේ ග්ලයිසීමික් දර්ශකය (GI) අඩු බැවින් රුධිර ග්ලූකෝස් මට්ටම ක්‍රමයෙන් ඉහළ නංවන නිසා", "ඒවායේ පිෂ්ඨය කිසිසේත්ම නොමැති නිසා", "ඒවායේ සීනි අධික නිසා", "ඒවා පහසුවෙන් ජීර්ණය නොවන නිසා", "අඩු GI ආහාර මගින් රුධිරයට ග්ලූකෝස් අවශෝෂණය වීම සෙමින් පාලනය කර ඉන්සියුලින් ඉල්ලුම අඩු කරයි."),
        q("ආහාර වේලක ඇති ග්ලයිසීමික් දර්ශකය (Glycemic Index - GI) මගින් මනිනු ලබන්නේ කුමක්ද?", "ආහාරයක් ගත් පසු රුධිරයේ ග්ලූකෝස් මට්ටම ඉහළ යන වේගය", "ආහාරයේ ඇති ප්‍රෝටීන් ප්‍රතිශතය", "ආහාරයේ ඇති විටමින් ප්‍රමාණය", "ආහාරයේ කල්පැවැත්ම", "ඉහළ GI සහිත ආහාර රුධිර සීනි මට්ටම ක්ෂණිකව ඉහළ නංවන අතර අඩු GI ආහාර ක්‍රමයෙන් ඉහළ නංවයි."),
        q("ශ්‍රී ලංකාවේ සාම්ප්‍රදායික ආහාර සංස්කෘතියේ එන 'කොළ කැඳ' පානය කිරීමෙන් ලැබෙන සෞඛ්‍යමය වාසියක් නොවන්නේ කුමක්ද?", "ශරීරයට හානිකර ට්‍රාන්ස් මේද විශාල ප්‍රමාණයක් ලැබීම", "ශරීරයට ක්ෂුද්‍ර පෝෂක හා ප්‍රතිඔක්සිකාරක ලැබීම", "ආහාර ජීර්ණය පහසු කර බඩවැල් පිරිසිදු කිරීම", "ශරීරයේ ප්‍රතිශක්තිය වර්ධනය වීම", "කොළ කැඳ සෞඛ්‍යාරක්ෂිත පානයක් වන අතර එහි කිසිදු අහිතකර ට්‍රාන්ස් මේදයක් අඩංගු නොවේ."),
        q("ආහාර විෂවීමකදී බහුලවම දැකිය හැකි පොදු රෝග ලක්ෂණ ත්‍රිත්වය කුමක්ද?", "වමනය, දියර මලපහ පිටවීම (පාචනය) සහ උදරයේ වේදනාව", "සමේ ලප ඇතිවීම පමණි", "පාදවල ඉදිමීම පමණි", "හිසකෙස් ගැලවී යාම", "විෂබීජ හෝ විෂ ද්‍රව්‍ය ආහාර ජීර්ණ පද්ධතියට ඇතුළු වූ විට වමනය හා පාචනය මගින් ඒවා බැහැර කිරීමට සිරුර උත්සාහ කරයි."),
        q("ආහාර විෂවීමක් හෝ දරුණු පාචන තත්ත්වයක් ඇති වූ විට විජලනය වැළැක්වීමට දිය යුතු මූලිකම පානය කුමක්ද?", "ජීවනී (මුඛ ප්‍රතිජලන ලවණ ද්‍රාවණය - ORS)", "අධික සීනි සහිත කෝලා බීම", "උණුසුම් තේ කෝප්පයක්", "මිරිස් සහිත සැර සුප්", "ORS ද්‍රාවණය මගින් විජලනය වූ සිරුරට ජලය, සෝඩියම්, පොටෑසියම් සහ ග්ලූකෝස් නිසි අනුපාතයට සපයයි."),
        q("මුඛ ප්‍රතිජලන ලවණ පැකට්ටුවක් (ජීවනී) සාමාන්‍යයෙන් දිය කළ යුතු නිවැරදි ජල පරිමාව කොපමණද?", "පිරිසිදු නිවාගත් සිසිල් ජලය ලීටර් 1ක (වීදුරු 4ක)", "ජලය මිලිලීටර් 100ක", "ජලය ලීටර් 5ක", "උතුරන ජලය ලීටර් භාගයක", "නියමිත ජල පරිමාවට (1L) වඩා අඩු වුවහොත් හෝ වැඩි වුවහොත් ලවණ සාන්ද්‍රණය වෙනස් වී අහිතකර විය හැක."),
        q("වෙළඳපොළේ ඇති ආහාර භාණ්ඩයක 'Best Before' (නියමිත දිනයට පෙර භාවිතය වඩාත් සුදුසුයි) යන්නෙන් අදහස් වන්නේ කුමක්ද?", "එම දිනයට පෙර ආහාරයේ ඉහළම ගුණාත්මකභාවය සහ රසය පවතින බව", "එම දිනයෙන් පසු පරිභෝජනය කළහොත් වහාම මරණය සිදුවන බව", "ආහාරය පිසින දිනය", "ආහාරය ඇසුරුම් කළ දිනය", "Best Before දිනයෙන් පසු ගුණාත්මකභාවය මඳක් අඩුවිය හැකි නමුත් ආහාරය වහා විෂ වීමක් අදහස් නොවේ."),
        q("ආහාරයක් පිසීමට පෙර පිරිසිදු කිරීමේදී අනුගමනය කළ යුතු හොඳ පුරුද්දක් වන්නේ කුමක්ද?", "එළවළු සහ පලතුරු ගලායන ජලයෙන් හොඳින් සෝදා පිරිසිදු කිරීම", "කෘමිනාශක ඉවත් කිරීමට සබන් හෝ ඩිටර්ජන්ට් යොදා සේදීම", "සේදීමකින් තොරව කෙළින්ම කපා පිසීම", "දින ගණනක් වතුරේ දමා තැබීම", "ගලායන ජලයෙන් සේදීමෙන් මතුපිට ඇති දූවිලි, ක්ෂුද්‍රජීවීන් හා කෘමිනාශක අවශේෂ සැලකිය යුතු ලෙස ඉවත් වේ."),
        q("මස් සහ මාළු පිසීමේදී තාපය මගින් ප්‍රෝටීනවලට සිදුවන මූලික රසායනික වෙනස කුමක්ද?", "ප්‍රෝටීන විස්වභාවීකරණය වී (Denaturation) ජීර්ණය පහසු වීම", "ප්‍රෝටීන කාබෝහයිඩ්‍රේට් බවට පත්වීම", "ප්‍රෝටීන විනාශ වී අතුරුදහන් වීම", "ප්‍රෝටීන මේදය බවට පත්වීම", "තාපය මගින් සංකීර්ණ ප්‍රෝටීන් ව්‍යුහය ලිහිල් වී ආහාර ජීර්ණ එන්සයිමවලට පහසුවෙන් ක්‍රියා කළ හැකි වේ."),
        q("ආහාර පිසීමේදී අනුගමනය නොකළ යුතු සෞඛ්‍යයට අහිතකර ක්‍රියාවක් කුමක්ද?", "එකම තෙල් භාජනයෙන් නැවත නැවත ආහාර ගැඹුරු තෙලේ බැදීම", "වාෂ්පයෙන් තැම්බීම", "අඩු ලුණු ප්‍රමාණයක් භාවිතය", "නැවුම් කුළුබඩු යෙදීම", "නැවත නැවත රත් කළ තෙල්වල පිළිකාකාරක පෙරොක්සයිඩ හා ට්‍රාන්ස් මේද විශාල වශයෙන් එකතු වේ."),
        q("ආහාර ජීර්ණ පද්ධතියේ ප්‍රධානම අවශෝෂණ කලාපය වන කුඩා අන්ත්‍රයේ සාමාන්‍ය දිග ආසන්න වශයෙන් මීටර් කීයද?", "මීටර් 6ක් පමණ (අඩි 20ක් පමණ)", "මීටර් 1ක් පමණ", "මීටර් 12ක් පමණ", "සෙන්ටිමීටර් 50ක් පමණ", "කුඩා අන්ත්‍රය දිගින් මීටර් 6ක් පමණ වන අතර එහි අංගුලිකා මගින් අවශෝෂණ මතුපිට වර්ගඵලය ටෙනිස් පිටියක් තරම් විශාල කරයි."),
        q("ආමාශ බිත්තියේ ඇති ආමාශයික ග්‍රන්ථිවලින් ස්‍රාවය වන හයිඩ්‍රොක්ලෝරික් අම්ලයේ (HCl) ප්‍රධාන කාර්යය කුමක්ද?", "ආහාර සමග එන විෂබීජ විනාශ කිරීම සහ පෙප්සින් එන්සයිමයට අවශ්‍ය ආම්ලික මාධ්‍යය සැපයීම", "මේදය සම්පූර්ණයෙන් දියකර හැරීම", "පිෂ්ඨය අවශෝෂණය කිරීම", "ආහාරයේ රසය පැණිරස කිරීම", "HCl ආම්ලික පරිසරය (pH 1.5 - 2.0) මගින් ක්ෂුද්‍රජීවීන් නසා පෙප්සිනොජන් සක්‍රීය පෙප්සින් බවට පත් කරයි."),
        q("ආමාශයික යුෂයේ ඇති ප්‍රබල අම්ලයෙන් සහ පෙප්සින් එන්සයිමයෙන් ආමාශ බිත්තිය ආරක්ෂා කරන්නේ කුමන ස්ථරය මගින්ද?", "ශ්ලේෂ්මල ස්ථරය (Mucus Layer)", "මේද ස්ථරය", "රුධිර නාල ස්ථරය", "ස්නායු ස්ථරය", "ආමාශයික ශ්ලේෂ්මල සෛලවලින් ස්‍රාවය වන ඝන ශ්ලේෂ්මලය ආමාශ බිත්තිය ස්වයං-ජීර්ණය වීමෙන් ආරක්ෂා කරයි."),
        q("දීර්ඝ වේලාවක් කුසගින්නේ සිටීම, වේලාවට ආහාර නොගැනීම සහ මානසික ආතතිය නිසා ආමාශ බිත්තියේ ඇතිවන තුවාල තත්ත්වය කුමක්ද?", "ගැස්ට්‍රයිටිස් හෙවත් ආමාශ ප්‍රදාහය (Gastritis)", "කොලයිටිස්", "හෙපටයිටිස්", "ඇපෙන්ඩිසයිටිස්", "ආහාර නොමැති විට ආමාශයික අම්ලය ආමාශ පටක ඛාදනය කිරීමෙන් ගැස්ට්‍රයිටිස් හටගනී."),
        q("ආහාර ජීර්ණ පද්ධතියේ අග්න්‍යාසය මගින් බහිස්ස්‍රාවී ග්‍රන්ථියක් ලෙස ආහාර ජීර්ණයට නිකුත් කරන යුෂය කුමක්ද?", "අග්න්‍යාසයික යුෂය (Pancreatic Juice)", "ආමාශයික යුෂය", "ඛේටය", "පිත", "අග්න්‍යාසයික යුෂයේ ඇමයිලේස්, ට්‍රිප්සින් සහ ලයිපේස් යන ප්‍රධාන ආහාර ජීර්ණ එන්සයිම තුනම අඩංගු වේ."),
        q("කුඩා අන්ත්‍රයේ ග්‍රහණිකාව තුළට පිත්තාශයෙන් නිකුත් වන පිතෙහි ජීර්ණ එන්සයිම අඩංගු නොවුවද එය වැදගත් වන්නේ ඇයි?", "ආමාශයෙන් එන ආම්ලික ආහාරය භෂ්මීය කර මේදය එමල්සිභවනය කරන බැවින්", "ප්‍රෝටීන සම්පූර්ණයෙන් බිඳහෙළන බැවින්", "ග්ලූකෝස් සෑදීමට උපකාරී වන බැවින්", "විටමින් C නිපදවන බැවින්", "පිතෙහි ඇති පිත්ත ලවණ මගින් මේදය කුඩා බිඳිති බවට පත් කර එන්සයිම ක්‍රියාකාරිත්වයට ඉඩ සලසයි."),
        q("කුඩා අන්ත්‍රයේ අංගුලිකාවල ඇති මධ්‍යම වසා නාලය (Lacteal) මගින් රුධිරයට අවශෝෂණය කරගනු ලබන පෝෂක මොනවාද?", "මේද අම්ල සහ ග්ලිසරෝල්", "ග්ලූකෝස් සහ ඇමයිනෝ අම්ල", "ජලයේ දියවන විටමින් B සහ C", "ඛනිජ ලවණ සහ ජලය", "මේද අම්ල හා ග්ලිසරෝල් වසා වාහිනී (Lacteals) තුළට අවශෝෂණය වී පසුව රුධිර සංසරණයට එකතු වේ."),
        q("කුඩා අන්ත්‍රයේ අංගුලිකාවල ඇති රුධිර කේශනාලිකා දැල මගින් ඍජුවම අවශෝෂණය කරන්නේ කුමන පෝෂකද?", "ග්ලූකෝස්, ඇමයිනෝ අම්ල සහ ජලයේ දියවන විටමින්", "මේද අම්ල සහ ග්ලිසරෝල්", "නොදිරවූ සෙලියුලෝස්", "විශාල ප්‍රෝටීන් අණු", "සරල සීනි හා ඇමයිනෝ අම්ල රුධිර කේශනාලිකා හරහා අක්මා ප්‍රතිහාර ධමනිය ඔස්සේ අක්මාවට ගමන් කරයි."),
        q("අවශෝෂණය වූ ග්ලූකෝස් සහ ඇමයිනෝ අම්ල මුලින්ම ගමන් කරන්නේ කුමන ප්‍රධාන අවයවය වෙතද?", "අක්මාව (Liver)", "වකුගඩු", "හෘදය", "පෙනහළු", "අක්මා ප්‍රතිහාර ශිරාව (Hepatic Portal Vein) මගින් සියලුම අවශෝෂිත පෝෂක පරීක්ෂාව හා සැකසීම සඳහා අක්මාවට ගෙන යයි."),
        q("ශරීරයේ රුධිරයේ අතිරික්ත ග්ලූකෝස් පාලනය කිරීම සඳහා අක්මාව සහ පේශි තුළ ග්ලයිකොජන් ලෙස තැන්පත් කරවීමට උපකාරී වන හෝමෝනය කුමක්ද?", "ඉන්සියුලින් (Insulin)", "ග්ලුකොගන්", "තයිරොක්සින්", "ඇඩ්‍රිනලින්", "අග්න්‍යාසයේ බීටා සෛලවලින් ශ්‍රාවය වන ඉන්සියුලින් හෝමෝනය මගින් රුධිර ග්ලූකෝස් මට්ටම පාලනය කරයි."),
        q("රුධිරයේ ග්ලූකෝස් මට්ටම අඩු වූ විට අක්මාවේ ඇති ග්ලයිකොජන් නැවත ග්ලූකෝස් බවට බිඳහෙළන අග්න්‍යාසයික හෝමෝනය කුමක්ද?", "ග්ලුකොගන් (Glucagon)", "ඉන්සියුලින්", "ඊස්ට්‍රජන්", "ප්‍රොජෙස්ටරෝන්", "අග්න්‍යාසයේ ඇල්ෆා සෛල මගින් ශ්‍රාවය වන ග්ලුකොගන් මගින් රුධිර ග්ලූකෝස් මට්ටම ඉහළ නංවයි."),
        q("මිනිස් සිරුරේ ජලය සමතුලිතව පවත්වා ගැනීමට සහ සාන්ද්‍ර මුත්‍ර පිටකිරීම නියාමනය කිරීමට පිටියුටරි ග්‍රන්ථියෙන් ශ්‍රාවය වන හෝමෝනය කුමක්ද?", "ප්‍රතිඩයුරෙටික හෝමෝනය (ADH / වාසොප්‍රෙසින්)", "තයිරොක්සින්", "ඔක්සිටොසින්", "වර්ධක හෝමෝනය", "ADH හෝමෝනය මගින් වකුගඩු නාලිකාවලින් ජලය නැවත අවශෝෂණය කර විජලනයෙන් සිරුර ආරක්ෂා කරයි."),
        q("ශරීරයේ විජලනය හඳුනාගත හැකි සරලම සායනික බාහිර ලක්ෂණයක් වන්නේ කුමක්ද?", "මුත්‍ර තද කහ පැහැවීම සහ මුඛය වියළී පිපාසය ඇතිවීම", "නිතර නිතර මුත්‍ර පිටවීම", "මුහුණ ඉදිමීම", "ශරීර බර එකවර වැඩිවීම", "ශරීරයේ ජලය අඩු වූ විට වකුගඩු මගින් ජලය ඉතිරි කර සාන්ද්‍ර තද කහ පැහැති මුත්‍ර පිටකරයි."),
        q("පාසල් ක්‍රීඩා උළෙලකදී හෝ දැඩි හිරු රශ්මියේ ක්‍රීඩා කිරීමේදී ඇතිවිය හැකි 'තාප කම්පනය' (Heat Stroke) වළක්වා ගැනීමට ගත යුතු පියවර කුමක්ද?", "ක්‍රීඩාවට පෙර, අතරතුර සහ පසුව ප්‍රමාණවත් තරම් ජලය සහ ලවණ පානය කිරීම", "ඝන ඇඳුම් ඇඳීම", "ජලය කිසිසේත් නොබී සිටීම", "දැඩිව කුසගින්නේ සිටීම", "ප්‍රමාණවත් තරල ලබාගැනීමෙන් දහඩිය දැමීම මගින් සිරුරේ අභ්‍යන්තර උෂ්ණත්වය නියතව තබාගත හැක."),
        q("ආහාර පරිභෝජනයේදී ශ්‍රී ලංකා සෞඛ්‍ය අමාත්‍යාංශය මගින් නිර්දේශිත 'දිනකට ගත යුතු උපරිම එකතු කළ සීනි ප්‍රමාණය' ආසන්න වශයෙන් කොපමණද?", "තේ හැඳි 6කට වඩා අඩුවෙන් (ග්‍රෑම් 25-30 පමණ)", "මේස හැඳි 10ක්", "සීනි ග්‍රෑම් 100ක්", "තේ හැඳි 20ක්", "දිනකට තේ හැඳි 6කට වඩා අඩුවෙන් එකතු කළ සීනි භාවිතය තරබාරුකම හා දියවැඩියාව වළක්වා ගැනීමට උපකාරී වේ."),
        q("අධික සීනි භාවිතය නිසා රුධිරයේ අතිරික්ත ග්ලූකෝස් ශරීරය තුළ කුමන ආකාරයට පරිවර්තනය වී තැන්පත් වේද?", "ට්‍රයිග්ලිසරයිඩ මේදය ලෙස ඇඩිපෝස් පටකවල", "අස්ථිවල කැල්සියම් ලෙස", "රුධිරයේ හිමොග්ලොබින් ලෙස", "ප්‍රෝටීන ලෙස පේශිවල", "අක්මාව මගින් අතිරික්ත ග්ලූකෝස් මේදය බවට පත්කර උදරය හා සම යට තැන්පත් කරයි."),
        q("තරබාරු බව සහ උදරීය මේදය බහුල පුද්ගලයන්ට දෙවන වර්ගයේ දියවැඩියාව වැළඳීමේ ප්‍රධාන යාන්ත්‍රණය කුමක්ද?", "ඉන්සියුලින් ප්‍රතිරෝධීතාවය (Insulin Resistance) ඇතිවීම", "ඉන්සියුලින් හෝමෝනය සම්පූර්ණයෙන් නැතිවීම", "ග්ලූකෝස් අවශෝෂණය නතර වීම", "වකුගඩු ක්‍රියාවලිය අඩාල වීම", "මේද සෛල බහුල වීම නිසා සිරුරේ සෛල ඉන්සියුලින් හෝමෝනයට නිසි ප්‍රතිචාර නොදක්වයි."),
        q("ශ්‍රී ලංකාවේ වැඩිහිටියන් අතර බහුලව දැකිය හැකි 'පරිවෘත්තීය සහලක්ෂණය' (Metabolic Syndrome) සඳහා අයත් නොවන සාධකය කුමක්ද?", "ඉතා ඉහළ කායික ක්‍රියාශීලීභාවය සහ අඩු ශරීර බර", "උදරීය තරබාරුකම (ඉහළ ඉණ වටප්‍රමාණය)", "අධික රුධිර පීඩනය", "රුධිරයේ අධික සීනි හා ට්‍රයිග්ලිසරයිඩ මට්ටම", "කායික ක්‍රියාශීලී බව පරිවෘත්තීය සහලක්ෂණය වළක්වන ප්‍රධානතම සෞඛ්‍ය සම්පන්න පුරුද්දයි."),
        q("පාසල් සිසුන් අතර පෝෂණ තත්ත්වය නංවාලීම සඳහා රජය මගින් ක්‍රියාත්මක කරනු ලබන ප්‍රධාන වැඩසටහනක් කුමක්ද?", "ප්‍රාථමික හා ද්විතීයික ශ්‍රේණිවල සිසුන්ට නොමිලේ පෝෂණීය උදෑසන ආහාර වේලක් ලබාදීම", "පැණිබීම නොමිලේ බෙදාහැරීම", "ක්ෂණික ආහාර ප්‍රවර්ධනය කිරීම", "විටමින් පෙති පමණක් ආහාරය වෙනුවට දීම", "පාසල් දිවා ආහාර වැඩසටහන මගින් අඩු ආදායම්ලාභී සිසුන්ගේ මන්දපෝෂණය හා ක්ලාන්තය වළක්වයි."),
        q("අධික ලෙස කෝපි පානය කිරීම නිසා ශරීරයේ කුමන ක්‍රියාවලියට බාධා සිදුවේද?", "යකඩ සහ කැල්සියම් අවශෝෂණය අඩු වී විජලනය උත්තේජනය වීම", "රුධිර පීඩනය සාමාන්‍ය වීම", "නින්ද වැඩිවීම", "ශරීර බර ක්ෂණිකව වැඩිවීම", "කැෆේන් ඩයියුරෙටික් ගුණයක් සහිත බැවින් ජලය පිටවීම වැඩි කරන අතර ඛනිජ අවශෝෂණය අවහිර කරයි."),
        q("ප්‍රෝටීන ඌනතාවය නිසා ඇතිවන ක්වාෂියෝකර් රෝගයේදී උදරය ඉදිරියට නෙරා ඒමට (ශෝථය) හේතුව කුමක්ද?", "රුධිර ප්ලාස්මාවේ ඇල්බියුමින් අඩුවීම නිසා අන්තර් සෛලීය අවකාශවල තරල එක්රැස් වීම", "උදරයේ අධික මේදය තැන්පත් වීම", "උදරයේ අස්ථි විශාල වීම", "ආහාර වැඩිපුර ගැනීම", "ඇල්බියුමින් අඩුවීමෙන් ප්ලාස්මාවේ අවිකල පීඩනය පහත වැටී පටක තුළට ජලය කාන්දු වේ."),
        q("ශරීරයේ ඇති ප්‍රධාන බහිස්ස්‍රාවී ඉන්ද්‍රිය වන වකුගඩු නිරෝගීව තබාගැනීම සඳහා අත්‍යවශ්‍ය පෝෂණ පුරුද්ද කුමක්ද?", "දිනපතා ප්‍රමාණවත් තරම් පිරිසිදු ජලය පානය කිරීම සහ අධික ලුණු පරිභෝජනයෙන් වැළකීම", "අධික ප්‍රෝටීන් කුඩු නොකඩවා ගැනීම", "ජලය පානය සීමා කිරීම", "අධික පැණිබීම පානය කිරීම", "ජලය ප්‍රමාණවත් ලෙස ගැනීමෙන් වකුගඩුවල මුත්‍ර ගල් සෑදීම වැළකී අපද්‍රව්‍ය පහසුවෙන් පෙරී යයි."),
        q("ආහාර සැකසීමේදී 'දුම් ගැසීම' (Smoking) මගින් ආහාර කල්තබා ගන්නේ කුමන යාන්ත්‍රණයකින්ද?", "මතුපිට වියළීම සහ දුමේ අඩංගු ෆීනෝලීය සංයෝග මගින් ක්ෂුද්‍රජීවීන් විනාශ කිරීම", "ආහාරය අයිස් බවට පත්කිරීම මගින්", "ආහාරයේ රසය පමණක් වෙනස් කිරීමෙන්", "ආහාරයට ජලය එකතු කිරීම මගින්", "දුමෙහි ඇති රසායනික සංඝටක විෂබීජ නාශක ලෙස ක්‍රියා කරන අතර මතුපිට වියළීමද සිදු කරයි."),
        q("විනාකිරි (ඇසිටික් අම්ලය) යොදා අච්චාරු දැමීම මගින් ආහාර කල්තබා ගැනීමට හේතුවන විද්‍යාත්මක පදනම කුමක්ද?", "ආහාරයේ pH අගය පහත හෙළා ආම්ලික පරිසරයක් නිර්මාණය කිරීම මගින් ක්ෂුද්‍රජීවී වර්ධනය වැළැක්වීම", "ආහාරයේ උෂ්ණත්වය ඉහළ නැංවීම", "ආහාරයේ ඔක්සිජන් වැඩි කිරීම", "ආහාරයේ ලවණ ඉවත් කිරීම", "බොහෝ ව්‍යාධිජනක බැක්ටීරියාවලට අඩු pH සහිත ප්‍රබල ආම්ලික පරිසරයක ජීවත් විය නොහැක."),
        q("ආහාර පැකට්ටුවක අඩංගු ආහාරය කිසිදු කෘත්‍රිම රසායනික ද්‍රව්‍යයක් හෝ පළිබෝධනාශකයක් නොයොදා ස්වාභාවිකව වගා කළ බව හඟවන යෙදුම කුමක්ද?", "කාබනික ආහාර (Organic Foods)", "ක්ෂණික ආහාර", "ජාන විකරණය කළ ආහාර", "පැස්ටරීකෘත ආහාර", "කාබනික ගොවිතැනේදී කෘත්‍රිම පොහොර, වල්නාශක හෝ කෘමිනාශක කිසිවක් යොදා නොගනී."),
        q("ශරීරයේ බර පාලනය කරගැනීම සඳහා කුසගින්නේ නොසිට අනුගමනය කළ හැකි වඩාත්ම විද්‍යාත්මක ක්‍රමවේදය කුමක්ද?", "සමබල ආහාර වේලක් සමග නිතිපතා දෛනික ශාරීරික ව්‍යායාමවල නිරත වීම", "උදෑසන හා රාත්‍රී ආහාර වේල් මුළුමනින්ම අත්හැරීම", "වෙළඳපොළේ ඇති කෘත්‍රිම බර අඩුකරන පෙති වර්ග භාවිතය", "ජලය පමණක් බීම", "සෞඛ්‍ය සම්පන්න ආහාර පාලනය සහ ව්‍යායාම මගින් මාංශපේශී ආරක්ෂා කර ගනිමින් අනවශ්‍ය මේදය දහනය කරයි."),
        q("යොවුන් වියේ පසුවන ගැහැනු ළමයෙකුට මාසික ඔසප් චක්‍රය හේතුවෙන් සිදුවන රුධිර වහනය නිසා වැඩිපුර අවශ්‍ය වන පෝෂ්‍ය පදාර්ථය කුමක්ද?", "යකඩ සහ විටමින් C", "කැල්සියම් සහ සෝඩියම්", "කාබෝහයිඩ්‍රේට් සහ මේදය", "විටමින් A සහ විටමින් D", "ඔසප් වීමේදී රුධිරය පිටවීම නිසා හිමොග්ලොබින් මට්ටම ආරක්ෂා කර ගැනීමට යකඩ සහ එය අවශෝෂණයට විටමින් C අත්‍යවශ්‍ය වේ."),
        q("අවන්හලකින් ආහාර ගැනීමේදී හෝ මිලදී ගැනීමේදී ආහාර සුරක්ෂිතතාව වෙනුවෙන් පාරිභෝගිකයෙකු මූලිකවම සැලකිලිමත් විය යුතු කරුණක් නොවන්නේ කුමක්ද?", "ආහාර පිසින ස්ථානයේ සහ සේවකයන්ගේ පෞද්ගලික සනීපාරක්ෂාව", "ආහාරය පිරිනමන භාණ්ඩවල පිරිසිදුකම", "ආහාර වේලෙහි මිල ඉතා අධිකද යන්න පමණක් බැලීම", "ආහාරය නිසි උෂ්ණත්වයකින් (උණුසුම්ව) පිළිගන්වන්නේද යන්න", "ආහාරයක මිල එහි පිරිසිදුකම හෝ සුරක්ෂිතතාව සහතික නොකරන බැවින් සනීපාරක්ෂාව ප්‍රමුඛ විය යුතුය.")
    )
}
